<template><ResourceState :loading="loading&&!data" :error="error" @retry="refresh"/><template v-if="data"><div class="application-banner"><div><h2>{{data.environment||data.target}} <StateBadge :status="data.status"/></h2><p class="muted">{{data.packageName||data.action}} · {{data.id}}</p></div><RouterLink to="/tasks" class="button">返回任务中心</RouterLink></div><div v-if="data.message||data.error" class="notice" :class="data.error?'danger':''">{{data.message||data.error}}</div><div class="grid-two"><PanelCard title="执行步骤"><TaskSteps v-if="data.steps" :steps="data.steps" :node="route.params.node"/><dl v-else class="facts"><dt>操作</dt><dd>{{data.action}}</dd><dt>目标</dt><dd>{{data.target}}</dd><dt>结果</dt><dd><StateBadge :status="data.status"/></dd><dt>执行记录</dt><dd><pre>{{JSON.stringify(data.result,null,2)}}</pre></dd></dl></PanelCard><PanelCard title="任务信息"><div v-if="data.installerLog"><h3>原生安装器日志</h3><pre class="log-viewer">{{data.installerLog}}</pre></div><dl class="facts"><dt>提交人</dt><dd>{{data.actor}}</dd><dt>创建时间</dt><dd>{{dateTime(data.createdAt||data.created)}}</dd><dt>更新时间</dt><dd>{{dateTime(data.updatedAt||data.updated)}}</dd><dt>作用实例</dt><dd>{{route.params.kind==='maintenance'?'本地管理平台':route.params.node}}</dd><dt v-if="data.version">版本</dt><dd v-if="data.version">{{data.version}}</dd></dl><div v-if="admin&&route.params.kind==='deployment'" class="toolbar" style="margin-top:22px"><button v-for="action in availableActions" :key="action.id" @click="selectedAction=action;confirmation=''">{{action.label}}</button></div><form v-if="selectedAction" @submit.prevent="control"><div class="notice warning">{{selectedAction.description}}仅作用于环境 {{data.environment}}，保留数据卷。</div><label>输入环境名称确认<input v-model="confirmation" :placeholder="data.environment" required></label><p v-if="actionError" class="notice danger" role="alert">{{actionError}}</p><button class="primary" :disabled="busy||confirmation!==data.environment">确认{{selectedAction.label}}</button><button type="button" @click="selectedAction=null">取消</button></form><div v-if="data.recovery" class="notice" style="margin-top:20px"><strong>失败后恢复</strong> <StateBadge :status="data.recovery.status"/><p v-if="data.recovery.error">{{data.recovery.error}}</p></div><div v-if="data.links?.length" style="margin-top:24px"><h3>应用入口</h3><p v-for="link in data.links" :key="link.url"><a :href="link.url" target="_blank" rel="noopener">{{link.name}} ↗</a></p></div></PanelCard></div></template></template>
<script setup>
import {computed,ref} from 'vue';import {maintenanceJob} from '../../api/platform';import {useRoute} from 'vue-router';import {deploymentsApi} from '../../api/deployments';import {infrastructureApi} from '../../api/infrastructure';import {useResource} from '../../composables/useResource';import {useSession} from '../../stores/session';import {useCluster} from '../../stores/cluster';import {dateTime} from '../../utils/format';import PanelCard from '../../components/ui/PanelCard.vue';import StateBadge from '../../components/ui/StateBadge.vue';import ResourceState from '../../components/ui/ResourceState.vue';import TaskSteps from '../../components/tasks/TaskSteps.vue';
const route=useRoute(),{admin}=useSession(),cluster=useCluster(),selectedAction=ref(null),confirmation=ref(''),busy=ref(false),actionError=ref('');const {data,loading,error,refresh}=useResource(signal=>route.params.kind==='maintenance'?maintenanceJob(route.params.id,signal):route.params.kind==='deployment'?deploymentsApi.job(route.params.node,route.params.id,signal):infrastructureApi.job(route.params.node,route.params.id,signal),{interval:3000});
const availableActions=computed(()=>{const job=data.value||{},actions=[];if((['failed','interrupted','cancelled'].includes(job.status)||(job.packageName==='runtime-os'&&job.status==='recovery_required')))actions.push({id:'resume',label:'恢复执行',description:'将先核对已创建资源与部署记录，再恢复未完成步骤。'});if(['running','queued'].includes(job.status))actions.push({id:'cancel',label:'取消任务',description:'请求在安全边界取消，已经执行的步骤保留记录。'});if(job.active&&job.status==='succeeded')actions.push({id:'stop',label:'停止应用',description:'按依赖顺序停止此环境的业务组件。'});if(job.status==='stopped')actions.push({id:'start',label:'启动应用',description:'按依赖顺序启动并检查此环境。'});if(job.previousRun&&job.active&&job.status==='succeeded')actions.push({id:'rollback',label:'回滚版本',description:'恢复保留的上一版本容器和兼容配置。'});return actions;});
async function control(){busy.value=true;actionError.value='';try{await deploymentsApi.control(route.params.node,route.params.id,selectedAction.value.id);selectedAction.value=null;await refresh();await cluster.refresh();}catch(e){actionError.value=e.message;}finally{busy.value=false;}}
</script>
